#'
#' Example dataset shipped with ClinicoPath.
#' Used in the tests of \code{advancedbarplot}, \code{advancedraincloud}, \code{agepyramid}, \code{agreement}, \code{autoeda}, \code{basegraphics}, \code{bbcplots}, \code{checkdata}, \code{chisqposttest}, \code{ciSingle}, \code{classification}, \code{contTables}, \code{contTablesPaired}, \code{coxdiagnostics}, \code{crosstable}, \code{crosstablepivot}, \code{dataquality}, \code{decision}, \code{decisioncurve}, \code{desctools}, \code{economistplots}, \code{enhancedcrosstable}, \code{enhancedtables}, \code{icccoeff}, \code{jcorrelation}, \code{jextractggstats}, \code{jforestmodel}, \code{jggheatmap}, \code{jjbarstats}, \code{jjbetweenstats}, \code{jjscatterstats}, \code{latentbiomarker}, \code{oddsratio}, \code{outlierdetection}, \code{timeinterval}.
#' Several data files define this name (\code{histopathology.rda}, \code{histopathologyDescriptives.rda}), possibly with different contents; the lazy-loaded object, described here, comes from \code{histopathologyDescriptives.rda}.
#'
#' @format A data frame (spec_tbl_df) with 250 rows and 38 variables:
#' \describe{
#'   \item{\code{ID}}{numeric, 1 to 250}
#'   \item{\code{Name}}{character; 249 distinct values; 1 missing}
#'   \item{\code{Sex}}{character: Female, Male; 1 missing}
#'   \item{\code{Age}}{numeric, 25 to 73; 1 missing}
#'   \item{\code{Race}}{character: Asian, Bi-Racial, Black, Hawaiian, Hispanic, Native, White; 1 missing}
#'   \item{\code{PreinvasiveComponent}}{character: Absent, Present; 1 missing}
#'   \item{\code{LVI}}{character: Absent, Present; 1 missing}
#'   \item{\code{PNI}}{character: Absent, Present; 1 missing}
#'   \item{\code{LastFollowUpDate}}{character; 12 distinct values; 1 missing}
#'   \item{\code{Death}}{character: \enc{DOĞRU}{DOGRU}, \enc{YANLIŞ}{YANLIS}; 1 missing}
#'   \item{\code{Group}}{character: Control, Treatment; 1 missing}
#'   \item{\code{Grade}}{numeric, 1 to 3; 1 missing}
#'   \item{\code{TStage}}{numeric, 1 to 4; 1 missing}
#'   \item{\code{Anti-X-intensity}}{numeric, 1 to 3; 1 missing}
#'   \item{\code{Anti-Y-intensity}}{numeric, 1 to 3; 1 missing}
#'   \item{\code{LymphNodeMetastasis}}{character: Absent, Present; 1 missing}
#'   \item{\code{Valid}}{character: \enc{DOĞRU}{DOGRU}, \enc{YANLIŞ}{YANLIS}; 1 missing}
